import{_ as l,a0 as o,w as r,s as d,I as s,x as n,a1 as i,A as p,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"如何在免費 WiFi 中保護隱私（四） | LCTT x X-CMD","titleTemplate":false,"description":"如何在免費 WiFi 中保護隱私（四） | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在免費 WiFi 中保護隱私（四） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在免費 WiFi 中保護隱私（四） | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210806 Access OpenVPN from a client computer","title":"如何在免費 WiFi 中保護隱私（四）","tag":"202108","desc":""},"relativePath":"202108/20210806 Access OpenVPN from a client computer.md","filePath":"[post].md"}'),g={name:"202108/20210806 Access OpenVPN from a client computer.md"};function u(f,e,k,h,m,b){const t=o("Link");return r(),d("div",null,[e[30]||(e[30]=s("h1",{id:"如何在免費-wifi-中保護隱私-四",tabindex:"-1"},[n("如何在免費 WiFi 中保護隱私（四） "),s("a",{class:"header-anchor",href:"#如何在免費-wifi-中保護隱私-四","aria-label":"Permalink to “如何在免費 WiFi 中保護隱私（四）”"},"​")],-1)),e[31]||(e[31]=s("blockquote",null,[s("p",null,"在 Linux 上安裝好“虛擬專用網絡” 之後，是時候使用它了。")],-1)),e[32]||(e[32]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/24/101214ng2afee2gmefgj5z.jpg",alt:""})],-1)),e[33]||(e[33]=s("p",null,"0penVPN 在兩點之間創建了一個加密通道，以阻止第三方訪問你的網絡流量數據。通過設置你的 “虛擬專用網絡” 服務，你可以成為你自己的 “虛擬專用網絡” 服務商。許多流行的 “虛擬專用網絡” 服務都使用 0penVPN，所以當你可以掌控自己的網絡時，為什麼還要將你的網絡連接綁定到特定的提供商呢？",-1)),s("p",null,[e[3]||(e[3]=n("本系列的 ",-1)),i(t,{href:"https://linux.cn/article-13680-1.html"},{default:p(()=>[...e[0]||(e[0]=[n("第一篇文章",-1)])]),_:1}),e[4]||(e[4]=n(" 安裝了一個“虛擬專用網絡” 的服務器，",-1)),i(t,{href:"https://linux.cn/article-13702-1.html"},{default:p(()=>[...e[1]||(e[1]=[n("第二篇文章",-1)])]),_:1}),e[5]||(e[5]=n(" 介紹瞭如何安裝和配置一個 0penVPN 服務軟件，",-1)),i(t,{href:"https://linux.cn/article-13707-1.html"},{default:p(()=>[...e[2]||(e[2]=[n("第三篇文章",-1)])]),_:1}),e[6]||(e[6]=n(" 解釋瞭如何配置防火牆並啓動你的 0penVPN 服務。第四篇也是最後一篇文章將演示如何從客户端計算機使用你的 0penVPN 服務器。這就是你做了前三篇文章中所有工作的原因！",-1))]),e[34]||(e[34]=a(`<h3 id="創建客户端證書" tabindex="-1">創建客户端證書 <a class="header-anchor" href="#創建客户端證書" aria-label="Permalink to “創建客户端證書”">​</a></h3><p>請記住，0penVPN 的身份驗證方法要求服務器和客户端都擁有某些東西（證書）並知道某些東西（口令）。是時候設置它了。</p><p>首先，為你的客户端計算機創建一個客户端證書和一個私鑰。在你的 0penVPN 服務器上，生成證書請求。它會要求你輸入密碼；確保你記住它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/ca</span></span>
<span class="line"><span>$ sudo /etc/openvpn/easy-rsa/easyrsa \\</span></span>
<span class="line"><span>  gen-req greglaptop</span></span></code></pre></div><p>本例中，<code>greglaptop</code> 是創建證書的客户端計算機主機名。</p><p>無需將請求導入證書頒發機構（CA），因為它已經存在。審查它以確保請求存在：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /etc/openvpn/ca</span></span>
<span class="line"><span>$ /etc/openvpn/easy-rsa/easyrsa \\</span></span>
<span class="line"><span>  show-req greglaptop</span></span></code></pre></div><p>你也可以以客户端身份簽署請求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /etc/openvpn/easy-rsa/easyrsa \\</span></span>
<span class="line"><span>  sign-req client greglaptop</span></span></code></pre></div><h3 id="安裝-0penvpn-客户端軟件" tabindex="-1">安裝 0penVPN 客户端軟件 <a class="header-anchor" href="#安裝-0penvpn-客户端軟件" aria-label="Permalink to “安裝 0penVPN 客户端軟件”">​</a></h3><p>在 Linux 系統上，網絡管理器可能已經包含了一個 0penVPN 客户端。如果沒有，你可以安裝插件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install NetworkManager-openvpn</span></span></code></pre></div><p>在 Windows 系統上，你必須從 0penVPN 下載網頁下載和安裝 0penVPN 客户端。啓動安裝程序並按照提示操作。</p><h3 id="複製證書和私鑰到客户端" tabindex="-1">複製證書和私鑰到客户端 <a class="header-anchor" href="#複製證書和私鑰到客户端" aria-label="Permalink to “複製證書和私鑰到客户端”">​</a></h3>`,14)),s("p",null,[e[8]||(e[8]=n("現在你的客户端需要你為其生成的身份驗證憑據。你在服務器上生成了這些，因此你必須將它們傳輸到你的客户端。我推薦使用 SSH 來完成傳輸。在 Linux 系統上，通過 ",-1)),e[9]||(e[9]=s("code",null,"scp",-1)),e[10]||(e[10]=n(" 命令實現。在 Windows 系統上，你可以以管理員身份運行 ",-1)),i(t,{href:"https://winscp.net/eng/index.php"},{default:p(()=>[...e[7]||(e[7]=[n("WinSCP",-1)])]),_:1}),e[11]||(e[11]=n(" 來推送證書和密鑰。",-1))]),e[35]||(e[35]=a(`<p>假設客户端名稱為 <code>greglaptop</code>，那麼證書和私鑰的文件名以及服務的位置如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/etc/openvpn/ca/pki/issued/greglaptop.crt</span></span>
<span class="line"><span>/etc/openvpn/ca/pki/private/greglaptop.key</span></span>
<span class="line"><span>/etc/openvpn/ca/pki/issued/ca.crt</span></span></code></pre></div><p>在 Linux 系統上，複製這些文件到 <code>/etc/pki/tls/certs</code> 目錄。在 Windows 系統上，複製它們到 <code>C:\\Program Files\\OpenVPN\\config</code> 目錄。</p><h3 id="複製和自定義客户端配置文件" tabindex="-1">複製和自定義客户端配置文件 <a class="header-anchor" href="#複製和自定義客户端配置文件" aria-label="Permalink to “複製和自定義客户端配置文件”">​</a></h3><p>在 Linux 系統上，你可以複製服務器上的 <code>/etc/openvpn/client/OVPNclient2020.ovpn</code> 文件到 <code>/etc/NetworkManager/system-connections/</code> 目錄，或者你也可以導航到系統設置中的網絡管理器添加一個“虛擬專用網絡” 連接。</p><p>連接類型選擇“<ruby>證書（TLS）<rt>Certificates(TLS)</rt></ruby>”。告知網絡管理器你從服務器上覆制的證書和密鑰。</p><p><img src="https://opensource.com/sites/default/files/uploads/network-manager-profile.jpg" alt="VPN displayed in Network Manager" title="VPN displayed in Network Manager"></p><p>在 Windows 系統上，以管理員身份運行 WinSCP，將服務器上的客户端配置模板 <code>/etc/openvpn/client/OVPNclient2020.ovpn</code> 文件複製到客户端上的 <code>C:\\Program Files\\OpenVPN\\config</code> 目錄。然後：</p><ul><li>重命名它以匹配上面的證書。</li><li>更改 CA 證書、客户端證書和密鑰的名稱以匹配上面從服務器複製的名稱。</li><li>修改 IP 信息，以匹配你的網絡。</li></ul><p>你需要超級管理員權限來編輯客户端配置文件。最簡單的方式就是以管理員身份啓動一個 CMD 窗口，然後從管理員 CMD 窗口啓動記事本來編輯此文件。</p><h3 id="將你的客户端連接到服務器" tabindex="-1">將你的客户端連接到服務器 <a class="header-anchor" href="#將你的客户端連接到服務器" aria-label="Permalink to “將你的客户端連接到服務器”">​</a></h3><p>在 Linux 系統上，網絡管理器會顯示你的 “虛擬專用網絡” 連接。選擇它進行連接。</p><p><img src="https://opensource.com/sites/default/files/uploads/network-manager-connect.jpg" alt="Add a connection in Network Manager" title="Add a“虛擬專用網絡” connection in Network Manager"></p><p>在 Windows 系統上，啓動 0penVPN 圖形用户界面。它會在任務欄右側的 Windows 系統托盤中生成一個圖標，通常位於 Windows 桌面的右下角。右鍵單擊圖標以連接、斷開連接或查看狀態。</p><p>對於第一次連接，編輯客户端配置文件的 <code>remote</code> 行以使用 0penVPN 服務器的內部 IP 地址。通過右鍵單擊 Windows 系統托盤中的 0penVPN 圖標並單擊“<ruby>連接<rt>Connect</rt></ruby>”，從辦公室網絡內部連接到服務器。調試此連接，這應該可以找到並解決問題，而不會出現任何防火牆問題，因為客户端和服務器都在防火牆的同一側。</p><p>接下來，編輯客户端配置文件的 <code>remote</code> 行以使用 0penVPN 服務器的公共 IP 地址。將 Windows 客户端連接到外部網絡並進行連接。調試有可能的問題。</p><h3 id="安全連接" tabindex="-1">安全連接 <a class="header-anchor" href="#安全連接" aria-label="Permalink to “安全連接”">​</a></h3><p>恭喜！你已經為其他客户端系統準備好了 0penVPN 網絡。對其餘客户端重複設置步驟。你甚至可以使用 Ansible 來分發證書和密鑰並使其保持最新。</p>`,18)),s("p",null,[e[13]||(e[13]=n("本文基於 D.Greg Scott 的 ",-1)),i(t,{href:"https://www.dgregscott.com/how-to-build-a-vpn-in-four-easy-steps-without-spending-one-penny/"},{default:p(()=>[...e[12]||(e[12]=[n("Blog",-1)])]),_:1}),e[14]||(e[14]=n("，經許可後重新使用。",-1))]),e[36]||(e[36]=s("hr",null,null,-1)),s("p",null,[e[16]||(e[16]=n("via: ",-1)),i(t,{href:"https://opensource.com/article/21/7/openvpn-client"},{default:p(()=>[...e[15]||(e[15]=[n("https://opensource.com/article/21/7/openvpn-client",-1)])]),_:1})]),s("p",null,[e[21]||(e[21]=n("作者：",-1)),i(t,{href:"https://opensource.com/users/greg-scott"},{default:p(()=>[...e[17]||(e[17]=[n("D. Greg Scott",-1)])]),_:1}),e[22]||(e[22]=n(" 選題：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:p(()=>[...e[18]||(e[18]=[n("lujun9972",-1)])]),_:1}),e[23]||(e[23]=n(" 譯者：",-1)),i(t,{href:"https://github.com/perfiffer"},{default:p(()=>[...e[19]||(e[19]=[n("perfiffer",-1)])]),_:1}),e[24]||(e[24]=n(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:p(()=>[...e[20]||(e[20]=[n("wxy",-1)])]),_:1})]),s("p",null,[e[27]||(e[27]=n("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[25]||(e[25]=[n("LCTT",-1)])]),_:1}),e[28]||(e[28]=n(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:p(()=>[...e[26]||(e[26]=[n("Linux中國",-1)])]),_:1}),e[29]||(e[29]=n(" 榮譽推出",-1))])])}const C=l(g,[["render",u]]);export{N as __pageData,C as default};
